(() => {
'use strict';
const core=window.RealNumbersLesson,$=s=>document.querySelector(s);
function math(host,source){const span=document.createElement('span');span.dataset.tex=source;host.replaceChildren(span);}
const examples={
zero:['0',['Bulat','Rasional','Real'],'Nol bukan bilangan asli dalam konvensi buku ini, tetapi nol adalah bilangan bulat dan dapat ditulis sebagai nol dibagi satu.'],
negative:['-3=\\frac{-3}{1}',['Bulat','Rasional','Real'],'Negatif tiga adalah bilangan bulat, bukan bilangan asli. Penyebut satu menunjukkan bahwa nilainya juga rasional.'],
fraction:['\\frac34',['Rasional','Real'],'Tiga per empat adalah rasional karena merupakan perbandingan dua bilangan bulat dengan penyebut bukan nol. Nilainya bukan bilangan bulat.'],
finite:['0{,}125=\\frac18',['Rasional','Real'],'Desimal berhenti ini dapat ditulis sebagai pecahan. Cara menuliskannya tidak mengubah nilainya.'],
recurring:['0{,}\\overline3=\\frac13',['Rasional','Real'],'Angka tiga berulang tanpa akhir. Desimal ini rasional, meskipun tidak berhenti.'],
root2:['\\sqrt2',['Irasional','Real'],'Akar dua tidak dapat ditulis sebagai perbandingan dua bilangan bulat. Menuliskan pendekatan desimal tidak mengubah jenis bilangan asalnya.'],
pi:['\\pi',['Irasional','Real'],'Pi adalah irasional. Nilainya bukan tepat 3,14 atau 22/7; kedua bilangan rasional itu hanya pendekatan.'],
root9:['\\sqrt9=3',['Asli','Bulat','Rasional','Real'],'Akar kuadrat utama dari sembilan adalah tiga. Jenis bilangan ditentukan oleh nilainya, bukan oleh tampilan simbol akar.'],
approx:['1{,}41421356=\\frac{141421356}{100000000}',['Rasional','Real'],'Desimal ini berhenti dan rasional. Nilainya mendekati akar dua, tetapi tidak sama persis dengan akar dua.']
};
function showExample(){const [source,groups,reason]=examples[$('#number-example').value];math($('#example-equation'),source);$('#example-groups').replaceChildren(...groups.map(g=>{const e=document.createElement('span');e.textContent=g;return e;}));$('#example-reason').textContent=reason;}
$('#number-example').addEventListener('change',showExample);showExample();
function showDecimal(){const n=Number($('#numerator').value),d=Number($('#denominator').value),v=core.decimal(n,d);$('#numerator-output').value=n;$('#denominator-output').value=d;math($('#decimal-equation'),`\\frac{${n}}{${d}}=${core.decimalTex(n,d)}`);$('#decimal-reason').textContent=v.terminates?'Pembagian ini berhenti. Nilainya tepat dan rasional.':'Bagian yang diberi garis atas berulang tanpa akhir. Ini nilai tepat bilangan rasional, bukan hasil pembulatan.';}
$('#numerator').addEventListener('input',showDecimal);$('#denominator').addEventListener('input',showDecimal);showDecimal();
const intervals={unit:[{n:0,d:1},{n:1,d:1}],fractions:[{n:1,d:3},{n:1,d:2}],negative:[{n:-1,d:1},{n:0,d:1}]};let left,right,steps;
function showInterval(){const m=core.midpoint(left,right);math($('#midpoint-equation'),`${core.tex(left)}<${core.tex(m)}<${core.tex(right)}`);$('#midpoint-reason').textContent=`Sudah diperkecil ${steps} kali. Nilai di tengah tetap lebih besar daripada ujung kiri dan lebih kecil daripada ujung kanan.`;$('#halve-interval').disabled=steps>=10;}
function resetInterval(){[left,right]=intervals[$('#interval-example').value].map(f=>({...f}));steps=0;showInterval();}
$('#interval-example').addEventListener('change',resetInterval);$('#reset-interval').addEventListener('click',resetInterval);$('#halve-interval').addEventListener('click',()=>{if(steps>=10)return;right=core.midpoint(left,right);steps++;showInterval();});resetInterval();
const questions=[
['Dengan konvensi bacaan ini, pernyataan mana yang benar tentang nol?',['Bulat, rasional, dan real; bukan asli.','Asli saja.','Irasional karena tidak positif.'],0,'Nol termasuk bilangan bulat dan dapat ditulis sebagai nol dibagi satu. Kita memakai konvensi bilangan asli dimulai dari satu.'],
['Apakah desimal dengan angka 6 berulang tanpa akhir pasti irasional?',['Ya, karena tidak berhenti.','Tidak; pola berulang itu menyatakan bilangan rasional.','Tidak dapat dijawab meskipun polanya sudah dinyatakan.'],1,'Desimal yang akhirnya berulang secara periodik adalah rasional. Contohnya nol koma enam berulang sama dengan dua per tiga.'],
['Bilangan akar kuadrat sembilan termasuk kelompok mana?',['Irasional karena memakai akar.','Real tetapi tidak rasional.','Asli, bulat, rasional, dan real.'],2,'Akar kuadrat utama sembilan adalah tiga. Kelompoknya mengikuti nilai tiga.'],
['Desimal berhenti 1,41421356 merupakan…',['Bilangan rasional yang mendekati akar dua.','Nilai tepat akar dua.','Bilangan irasional karena angkanya banyak.'],0,'Desimal berhenti dapat ditulis sebagai pecahan dengan penyebut pangkat sepuluh. Akar dua sendiri irasional.'],
['Adakah bilangan real di antara 0,1 dan 0,2?',['Tidak, karena keduanya berurutan.','Ada, misalnya 0,15, dan masih ada tak berhingga banyak lainnya.','Hanya ada satu, yaitu 0,15.'],1,'Nilai tengah berada di antara dua ujung. Kita dapat mengulang prosesnya pada interval yang lebih kecil.'],
['Agar bentuk p dibagi q menyatakan bilangan rasional, syaratnya…',['p dan q boleh sembarang bilangan real.','q harus positif, sedangkan p tidak boleh nol.','p dan q bilangan bulat, dan q bukan nol.'],2,'Syarat bilangan bulat pada pembilang dan penyebut penting. Perbandingan dua bilangan real sembarang tidak otomatis rasional.']
];const solved=new Set();
questions.forEach(([prompt,options,answer,why],i)=>{const box=document.createElement('fieldset'),legend=document.createElement('legend');legend.textContent=`${i+1}. ${prompt}`;box.append(legend);options.forEach((label,j)=>{const row=document.createElement('label'),radio=document.createElement('input');radio.type='radio';radio.name=`real-q${i}`;radio.value=String(j);row.append(radio,document.createTextNode(label));box.append(row);});const button=document.createElement('button');button.type='button';button.textContent='Periksa jawaban';const feedback=document.createElement('p');feedback.setAttribute('role','status');button.addEventListener('click',()=>{const selected=box.querySelector('input:checked');if(!selected){feedback.textContent='Pilih satu jawaban terlebih dahulu.';return;}const ok=Number(selected.value)===answer;if(ok)solved.add(i);feedback.textContent=(ok?'Tepat. ':'Belum tepat. ')+why;feedback.className=ok?'correct':'incorrect';$('#real-progress').textContent=`${solved.size} dari 6 latihan pernah dijawab tepat.`;});box.addEventListener('change',()=>{feedback.textContent='Jawaban berubah. Periksa kembali untuk melihat tanggapan.';feedback.className='';});box.append(button,feedback);$('#real-questions').append(box);});$('#real-progress').textContent='0 dari 6 latihan pernah dijawab tepat.';
try{$('#real-reflection').value=localStorage.getItem('fondasi-real-reflection')||'';}catch{$('#real-save').textContent='Catatan belum dapat dimuat. Salin catatan jika perlu.';}
$('#real-reflection').addEventListener('input',()=>{try{localStorage.setItem('fondasi-real-reflection',$('#real-reflection').value);$('#real-save').textContent='Catatan tersimpan di peramban ini.';}catch{$('#real-save').textContent='Catatan belum dapat disimpan. Salin jika ingin menyimpannya.';}});
})();
